import{_ as a,I as n,c as r,o as t,a3 as o,b as i,w as d,a as s,J as l,a4 as A}from"./chunks/framework.czLORLkK.js";const f=JSON.parse('{"title":"SyncAPIM 4-JVM 시스템 아키텍처 및 데이터베이스 설계","description":"SyncAPIM의 고성능 4-JVM 프로세스 분리 아키텍처(Admin, Receiver, Detector, Gateway), Redis 7 Stream 파이프라인 및 PostgreSQL 18.6 도메인 스키마를 설명합니다.","frontmatter":{"title":"SyncAPIM 4-JVM 시스템 아키텍처 및 데이터베이스 설계","sidebarTitle":"4-JVM 아키텍처 & DB 설계","description":"SyncAPIM의 고성능 4-JVM 프로세스 분리 아키텍처(Admin, Receiver, Detector, Gateway), Redis 7 Stream 파이프라인 및 PostgreSQL 18.6 도메인 스키마를 설명합니다.","head":[["meta",{"name":"keywords","content":"SyncAPIM 아키텍처, 4-JVM, sync-apim-admin, sync-apim-receiver, sync-apim-detector, sync-apim-gateway, PostgreSQL 18.6, pg_trgm, wapf_detect_event"}],["meta",{"property":"og:title","content":"SyncAPIM 4-JVM 시스템 아키텍처 및 데이터베이스 설계"}],["meta",{"property":"og:description","content":"초고속 패킷 수집·위협 탐지 부하 격리를 위한 4-JVM 아키텍처 및 PostgreSQL 18.6 단일 스토리지 설계"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/syncapim/architecture"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/syncapim/architecture"}]],"sort":2},"headers":[],"relativePath":"syncapim/architecture.md","filePath":"ko/syncapim/architecture.md","lastUpdated":1794045358000}'),E={name:"syncapim/architecture.md"};function p(B,e,C,g,m,y){const c=n("Mermaid");return t(),r("div",null,[e[1]||(e[1]=o('<h1 id="syncapim-4-jvm-시스템-아키텍처-및-데이터베이스-설계" tabindex="-1">SyncAPIM 4-JVM 시스템 아키텍처 및 데이터베이스 설계 <a class="header-anchor" href="#syncapim-4-jvm-시스템-아키텍처-및-데이터베이스-설계" aria-label="Permalink to “SyncAPIM 4-JVM 시스템 아키텍처 및 데이터베이스 설계”">​</a></h1><p><code>SyncAPIM</code>은 <strong>Java 25 (Virtual Threads)</strong>, <strong>Spring Boot 3.5.16</strong>, <strong>AgentScope Java (<code>io.agentscope:agentscope-harness</code>)</strong>, <strong>PostgreSQL 18.6 (<code>JSONB</code> + <code>pg_trgm</code>)</strong>, <strong>Redis 7 Stream</strong>, <strong>Vue 3 + Vben Admin (<code>@empasy/sync-apim-admin</code>)</strong> 표준 기술 스택 위에 구축된 고성능 API 모니터링 및 보안 에이전트 플랫폼입니다.</p><hr><h2 id="_1-성능-격리형-4-jvm-프로세스-아키텍처" tabindex="-1">1. 성능 격리형 4-JVM 프로세스 아키텍처 <a class="header-anchor" href="#_1-성능-격리형-4-jvm-프로세스-아키텍처" aria-label="Permalink to “1. 성능 격리형 4-JVM 프로세스 아키텍처”">​</a></h2><p>대규모 API 트래픽 환경에서 패킷 수집(I/O 집약)과 정규식·JWT 위협 탐지(CPU 집약) 부하가 관리자 콘솔이나 인라인 게이트웨이 응답 지연에 영향을 주지 않도록 <strong>4개의 독립된 JVM 프로세스</strong>로 분리하여 기동합니다.</p>',5)),(t(),i(A,null,{default:d(()=>[l(c,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20TrafficSources%20%5B%22%EB%B3%B4%ED%98%B8%20%EB%8C%80%EC%83%81%20API%20%ED%98%B8%EC%8A%A4%ED%8A%B8%20%26%20%EC%88%98%EC%A7%91%20%EC%97%90%EC%9D%B4%EC%A0%84%ED%8A%B8%22%5D%0A%20%20%20%20%20%20%20%20Beat%5B%22Packetbeat%20%2F%20Filebeat%5Cn(TCP%205044%20%2F%205055)%22%5D%0A%20%20%20%20%20%20%20%20Client%5B%22API%20%ED%81%B4%EB%9D%BC%EC%9D%B4%EC%96%B8%ED%8A%B8%20%EC%9A%94%EC%B2%AD%5Cn(HTTP%2FHTTPS)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SyncApimCluster%20%5B%22SyncAPIM%204-JVM%20%EB%8F%85%EB%A6%BD%20%ED%94%84%EB%A1%9C%EC%84%B8%EC%8A%A4%20%ED%81%B4%EB%9F%AC%EC%8A%A4%ED%84%B0%22%5D%0A%20%20%20%20%20%20%20%20GW%5B%22JVM%20%234%3A%20sync-apim-gateway%20(18091)%5Cn%EB%8F%99%EC%A0%81%20BlockedApiFilter%20%26%20%ED%8A%B8%EB%9E%98%ED%94%BD%20%EB%AF%B8%EB%9F%AC%EB%A7%81%22%5D%0A%20%20%20%20%20%20%20%20RCV%5B%22JVM%20%232%3A%20sync-apim-receiver%20(18090)%5CnVirtual%20Thread%20%ED%8C%A8%ED%82%B7%20%EB%9D%BC%EC%9A%B0%ED%84%B0%20%26%20%EC%88%98%EC%A7%91%20API%22%5D%0A%20%20%20%20%20%20%20%20DET%5B%22JVM%20%233%3A%20sync-apim-detector%20(18092)%5CnOpenAPI%203.0%20%EC%B6%94%EB%A1%A0%20%C2%B7%20WAF%20%EB%A3%B0%20%EB%A7%A4%EC%B9%AD%20%C2%B7%20PII%20%EB%A7%88%EC%8A%A4%ED%82%B9%22%5D%0A%20%20%20%20%20%20%20%20ADM%5B%22JVM%20%231%3A%20sync-apim-admin%20(18089)%5Cn%ED%86%B5%ED%95%A9%20%EA%B4%80%EC%A0%9C%20API%20%C2%B7%20%ED%86%B5%EA%B3%84%20%EB%B0%B0%EC%B9%98%20%C2%B7%20MCP%20Server%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Storage%20%5B%22%EC%A0%84%EC%82%AC%20%EB%8B%A8%EC%9D%BC%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%ED%94%8C%EB%A0%88%EC%9D%B8%22%5D%0A%20%20%20%20%20%20%20%20Redis%5B(%22Redis%207%5CnStream%3A%20job_queue%5CnCache%3A%20wapf%3Apolicy%3Arules%20%2F%20blocked%3Aendpoints%22)%5D%0A%20%20%20%20%20%20%20%20PG%5B(%22PostgreSQL%2018.6%20(sync_apim)%5Cnwapf_*%2017%EA%B0%9C%20%ED%85%8C%EC%9D%B4%EB%B8%94%20%2B%20pg_trgm%20GIN%20%EC%9D%B8%EB%8D%B1%EC%8A%A4%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Client%20--%3E%20GW%0A%20%20%20%20Beat%20--%3E%20RCV%0A%20%20%20%20GW%20--%3E%7C%EB%B9%84%EB%8F%99%EA%B8%B0%20%ED%8A%B8%EB%9E%98%ED%94%BD%20%EB%AF%B8%EB%9F%AC%EB%A7%81%7C%20RCV%0A%20%20%20%20RCV%20--%3E%7CXADD%20job_queue%7C%20Redis%0A%20%20%20%20Redis%20--%3E%7CXREADGROUP%7C%20DET%0A%20%20%20%20DET%20--%3E%7C%EC%97%94%EB%93%9C%ED%8F%AC%EC%9D%B8%ED%8A%B8%C2%B7%EC%8A%A4%ED%8E%99%C2%B7%ED%83%90%EC%A7%80%EC%9D%B4%EB%B2%A4%ED%8A%B8%20%EC%A0%80%EC%9E%A5%7C%20PG%0A%20%20%20%20ADM%20%3C--%3E%7C%EC%B9%B4%ED%83%88%EB%A1%9C%EA%B7%B8%C2%B7%EC%A0%95%EC%B1%85%C2%B7%ED%86%B5%EA%B3%84%C2%B7%EB%93%9C%EB%A6%AC%ED%94%84%ED%8A%B8%20%EA%B0%90%EC%82%AC%7C%20PG%0A%20%20%20%20ADM%20--%3E%7C%EC%A0%95%EC%B1%85%2F%EB%AF%BC%EA%B0%90%EC%A0%95%EB%B3%B4%2F%EC%B0%A8%EB%8B%A8%EB%AA%A9%EB%A1%9D%20%EC%8B%A4%EC%8B%9C%EA%B0%84%20%EB%8F%99%EA%B8%B0%ED%99%94%7C%20Redis%0A%20%20%20%20Redis%20--%3E%7C%EC%B0%A8%EB%8B%A8%20%EA%B2%BD%EB%A1%9C%20%EB%B0%8F%20%ED%83%90%EC%A7%80%20%EB%A3%B0%20%EC%A6%89%EC%8B%9C%20%EB%B0%98%EC%98%81%7C%20GW%0A%20%20%20%20Redis%20--%3E%7C%ED%83%90%EC%A7%80%20%EB%A3%B0%20%EB%B0%8F%20PII%20%ED%8C%A8%ED%84%B4%20%EC%BA%90%EC%8B%9C%20%EC%A1%B0%ED%9A%8C%7C%20DET%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="_1-1-jvm별-역할-및-포트-규격" tabindex="-1">1.1 JVM별 역할 및 포트 규격 <a class="header-anchor" href="#_1-1-jvm별-역할-및-포트-규격" aria-label="Permalink to “1.1 JVM별 역할 및 포트 규격”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">JVM 모듈명</th><th style="text-align:center;">호스트 포트 (컨테이너)</th><th style="text-align:left;">핵심 클래스</th><th style="text-align:left;">주요 역할 및 성능 격리 목적</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>sync-apim-admin</code></strong></td><td style="text-align:center;"><code>18089</code> (<code>8080</code>)</td><td style="text-align:left;"><code>WapfApiEndPointController</code>, <code>WapfPolicyController</code>, <code>ApimTrafficAggregationService</code>, <code>SyncApimAgent</code>, <code>ApimMcpController</code></td><td style="text-align:left;">11개 관제 화면 REST API(<code>/api/v1/apim/...</code>), 5분 주기 트래픽·위협 통계 집계 배치, <code>SyncVerse</code> 연동 6대 MCP 도구 서빙</td></tr><tr><td style="text-align:left;"><strong><code>sync-apim-receiver</code></strong></td><td style="text-align:center;"><code>18090</code> (<code>8081</code>)<br>TCP <code>5044</code>/<code>5055</code></td><td style="text-align:left;"><code>PacketReceiver</code>, <code>LumberjackRouter</code>, <code>RedisStreamProducerService</code>, <code>ApimReceiverController</code></td><td style="text-align:left;">Java 25 Virtual Threads 기반 비차단 TCP 소켓 서버 및 HTTP 수집 엔드포인트(<code>/api/v1/apim/receiver/ingest</code>) 운영, Redis Stream <code>job_queue</code> 적재</td></tr><tr><td style="text-align:left;"><strong><code>sync-apim-detector</code></strong></td><td style="text-align:center;"><code>18092</code> (<code>8090</code>)</td><td style="text-align:left;"><code>RedisStreamConsumer</code>, <code>DetectionRuleServiceImpl</code>, <code>WapfDetectRuleServiceImpl</code></td><td style="text-align:left;">Redis Stream 워커 스레드 풀에서 실시간 패킷 파싱, 엔드포인트 자동 등록, OpenAPI 3.0.1 명세 합성, 6대 WAF 정규식/JWT 위협 탐지 및 8대 PII 마스킹 후 PostgreSQL <code>wapf_detect_event</code> 저장</td></tr><tr><td style="text-align:left;"><strong><code>sync-apim-gateway</code></strong></td><td style="text-align:center;"><code>18091</code> (<code>8083</code>)</td><td style="text-align:left;"><code>BlockedApiFilter</code>, <code>BlockedApiRegistryService</code>, <code>ApimGatewayController</code></td><td style="text-align:left;">DB(<code>wapf_api_endpoint.block_status=&#39;1&#39;</code>) 및 Redis(<code>wapf:blocked:endpoints</code>)와 동기화되어 차단된 섀도우/고위험 API 호출을 <code>403 Forbidden</code>으로 즉시 차단하고 정상 트래픽을 <code>receiver</code>로 미러링</td></tr></tbody></table><hr><h2 id="_2-멀티모듈-디렉터리-및-maven-좌표-구조" tabindex="-1">2. 멀티모듈 디렉터리 및 Maven 좌표 구조 <a class="header-anchor" href="#_2-멀티모듈-디렉터리-및-maven-좌표-구조" aria-label="Permalink to “2. 멀티모듈 디렉터리 및 Maven 좌표 구조”">​</a></h2><p><code>sync-apim/Server/</code> 하위 모든 모듈은 전사 표준에 따라 <code>artifactId</code>와 물리 디렉터리명이 <code>1:1</code>로 일치합니다.</p><ul><li><strong>최상위 부모 POM</strong>: <code>com.empasy.sync.apim:sync-apim-parent:1.0.0-SNAPSHOT</code> (<code>sync-apim/pom.xml</code>)</li><li><strong>백엔드 부모 POM</strong>: <code>com.empasy.sync.apim:sync-apim-server-parent:1.0.0-SNAPSHOT</code> (<code>sync-apim/Server/pom.xml</code>)</li><li><strong>공통 및 코어 모듈</strong>: <ul><li><code>Server/sync-apim-common</code>: 17개 도메인 엔티티(<code>WapfApiEndPoint</code>, <code>WapfDetectEvent</code> 등), MyBatis-Plus Mapper, 공통 Service (<code>WapfOpenApiSpecServiceImpl</code> 드리프트 감사 엔진 포함)</li><li><code>Server/sync-apim-base-core</code>: <code>MybatisPlusConfig</code>, <code>RedisConfig</code>, <code>AuthInterceptor</code>, <code>GlobalExceptionHandler</code></li><li><code>Server/sync-apim-module-system</code>: 시스템 인증·인가 및 DB 동적 메뉴 공급(<code>/api/v1/apim/sys/permission/getUserPermissionByToken</code>)</li></ul></li></ul><hr><h2 id="_3-postgresql-18-6-도메인-데이터베이스-설계-db-02-schema-domain-sql" tabindex="-1">3. PostgreSQL 18.6 도메인 데이터베이스 설계 (<code>db/02_schema_domain.sql</code>) <a class="header-anchor" href="#_3-postgresql-18-6-도메인-데이터베이스-설계-db-02-schema-domain-sql" aria-label="Permalink to “3. PostgreSQL 18.6 도메인 데이터베이스 설계 (db/02_schema_domain.sql)”">​</a></h2><p>기존 MariaDB/MySQL + OpenSearch 이중 스토리지를 단일 <strong>PostgreSQL 18.6 (<code>sync_apim</code> 데이터베이스)</strong>으로 통합하여 운영 복잡도와 메모리 점유율을 낮추었습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">분류</th><th style="text-align:left;">물리 테이블명</th><th style="text-align:left;">주요 컬럼 및 설계 특징</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>에이전트 &amp; 호스트</strong></td><td style="text-align:left;"><code>wapf_agent</code>, <code>wapf_agent_host</code>, <code>wapf_host</code></td><td style="text-align:left;">수집 에이전트 마스터(SHA-256 <code>auth_key</code>), 보호 대상 API 호스트(<code>host</code>, <code>status</code>) 및 <code>N:M</code> 매핑</td></tr><tr><td style="text-align:left;"><strong>API 카탈로그</strong></td><td style="text-align:left;"><code>wapf_api_endpoint</code>, <code>wapf_api_endpoint_detail</code>, <code>wapf_api_endpoint_history</code></td><td style="text-align:left;">자동 발견된 <code>host</code> + <code>path</code> + <code>method</code> 고유 엔드포인트, 위험도 점수(<code>risk_score</code>), 차단 상태(<code>block_status</code>), 경로 병합 이력</td></tr><tr><td style="text-align:left;"><strong>데이터 필드 &amp; 명세</strong></td><td style="text-align:left;"><code>wapf_data_field</code>, <code>wapf_open_api_spec</code></td><td style="text-align:left;">요청/응답 섹션별(<code>REQ_QUERY</code>, <code>REQ_BODY</code>, <code>RES_BODY</code>) JSONPath 필드, 민감정보 매핑(<code>sensitivity_uuid</code>), OpenAPI 3.0.1 JSON 명세 및 드리프트 상태(<code>contract_status</code>, <code>drift_summary</code>)</td></tr><tr><td style="text-align:left;"><strong>WAF 정책 &amp; 탐지 룰</strong></td><td style="text-align:left;"><code>wapf_policy</code>, <code>wapf_policy_api_endpoint</code>, <code>wapf_policy_rule</code>, <code>wapf_rule</code></td><td style="text-align:left;">7대 보안 정책 마스터(<code>basic</code> 기본 정책 여부), 정책별 엔드포인트 적용 매핑, 6대 위협 탐지 정규식(<code>pattern</code>) 및 JWT 검증 옵션(<code>jwt_option</code>)</td></tr><tr><td style="text-align:left;"><strong>민감정보 &amp; 경보</strong></td><td style="text-align:left;"><code>wapf_sensitivity</code>, <code>wapf_email</code></td><td style="text-align:left;">8대 개인·금융 민감정보 탐지 정규식 마스터, 고위험 위협 발생 시 보안 담당자 경보 메일 발송 이력</td></tr><tr><td style="text-align:left;"><strong>시계열 통계</strong></td><td style="text-align:left;"><code>wapf_endpoint_average</code>, <code>wapf_rule_average</code></td><td style="text-align:left;">엔드포인트별 호출량 및 위협 탐지 룰별·심각도별 시계열 집계 테이블</td></tr><tr><td style="text-align:left;"><strong>실시간 탐지 이벤트</strong></td><td style="text-align:left;"><code>wapf_detect_event</code></td><td style="text-align:left;">패킷 요청/응답 헤더·파라미터·본문(<code>JSONB</code> 및 마스킹 텍스트), 위협 코드 배열(<code>threat_codes</code>), 위험도 점수, <code>pg_trgm</code> GIN 인덱스 기반 초고속 전문 검색</td></tr></tbody></table>',10))])}const D=a(E,[["render",p]]);export{f as __pageData,D as default};
